#!/usr/bin/env bash
# Positive control for compare_lint_runs.py (dispatch 2026-10-17-03). compare-control-expected.json
# was written by hand from the two control files' header comments, not generated by the script.
#   1. the script's JSON on the two controls equals the expected JSON        -> must MATCH
#   2. the same with one AFTER issue's id changed (KeptA -> NewW)            -> must DIFFER
# Check 2 shows check 1 can fail.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
script="$here/compare_lint_runs.py"
root="/home/runner/work/Forager/Forager"
tmp="$(mktemp -d)"; trap 'rm -rf "$tmp"' EXIT
same() { python3 -c 'import json,sys; sys.exit(0 if json.load(open(sys.argv[1]))==json.load(open(sys.argv[2])) else 1)' "$1" "$2"; }
status=0
python3 "$script" "$here/compare-control-before.xml" "$here/compare-control-after.xml" --root "$root" --json > "$tmp/a.json"
if same "$tmp/a.json" "$here/compare-control-expected.json"; then echo "check 1 PASS: output equals the hand-written expected comparison"
else echo "check 1 FAIL"; diff <(python3 -m json.tool --sort-keys "$tmp/a.json") <(python3 -m json.tool --sort-keys "$here/compare-control-expected.json") || true; status=1; fi
python3 - "$here/compare-control-after.xml" "$tmp/m.xml" <<'PY'
import sys
t = open(sys.argv[1]).read()
assert t.count('id="KeptA"') == 1
open(sys.argv[2], "w").write(t.replace('id="KeptA"', 'id="NewW"'))
PY
python3 "$script" "$here/compare-control-before.xml" "$tmp/m.xml" --root "$root" --json > "$tmp/m.json"
if same "$tmp/m.json" "$here/compare-control-expected.json"; then echo "check 2 FAIL: a one-id mutation still matched"; status=1
else echo "check 2 PASS: the one-id mutation was detected"; fi
echo; python3 "$script" "$here/compare-control-before.xml" "$here/compare-control-after.xml" --root "$root"
exit "$status"
